sql.if:
and tc.tre_code like concat(
    (select substring(g.guoku_id, 1, (g.level - 1) * 2)
       from edw.cm_guoku_dimnsn g where g.guoku_id = #{q.guokuId}), '%')

mapper.select:
select a.month_f_amt from edw.income_report_detail_stat a
 where a.s_tratrecode = #{q.treCode} and a.d_acct = #{q.bizDate}
   and a.statistics_code = #{q.statisticsCode} and a.c_bdglevel = #{q.budgetLevel}
   and a.s_tratrecode like concat((select substring(g.guoku_id, 1, (g.level - 1) * 2)
     from edw.cm_guoku_dimnsn g where g.guoku_id = #{q.guokuId}), '%')

select a.month_f_amt from edw.payout_report_detail_stat a
 where a.s_trecode = #{q.treCode} and a.d_acct = #{q.bizDate}
   and a.statistics_code = #{q.statisticsCode} and a.guoku_lvl = #{q.budgetLevel}
   and a.s_trecode like concat((select substring(g.guoku_id, 1, (g.level - 1) * 2)
     from edw.cm_guoku_dimnsn g where g.guoku_id = #{q.guokuId}), '%')
